            do
$$
    begin
        if not exists(select 1 from pg_constraint where conname = 'product_branch_child_fk') then
            alter table product_branch
                add constraint product_branch_child_fk
                    foreign key (child_product_id, city_id, branch_id) references product_branch (product_id, city_id, branch_id);
        end if;
    end;
$$
